content:
I’ll design a pure client‑side web app that lets you watch a YouTube Live stream while broadcasting your camera and viewing other participants – like a co‑watching party with video call. The demo uses only browser APIs (BroadcastChannel for signalling) so you can test it locally with multiple tabs, no server needed.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>LiveStream Watch Party + Video Call</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: system-ui, sans-serif;
      background: #0f0f0f;
      color: #fff;
      overflow: hidden;
      height: 100vh;
      display: flex;
      flex-direction: column;
    }
    .top-bar {
      padding: 12px;
      background: #1a1a1a;
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .top-bar input {
      padding: 8px 12px;
      border-radius: 6px;
      border: 1px solid #444;
      background: #2a2a2a;
      color: #fff;
      flex: 1;
      min-width: 200px;
    }
    .top-bar button {
      padding: 8px 16px;
      border-radius: 6px;
      border: none;
      background: #3ea6ff;
      color: #000;
      font-weight: bold;
      cursor: pointer;
    }
    .top-bar button.stop {
      background: #ff4d4d;
    }
    .main {
      flex: 1;
      display: flex;
      gap: 8px;
      padding: 8px;
      min-height: 0;
    }
    .youtube-container {
      flex: 3;
      background: #000;
      border-radius: 8px;
      overflow: hidden;
      position: relative;
    }
    .youtube-container iframe {
      width: 100%;
      height: 100%;
      border: none;
    }
    .self-view {
      position: absolute;
      bottom: 10px;
      right: 10px;
      width: 160px;
      height: 120px;
      background: #222;
      border-radius: 8px;
      overflow: hidden;
      border: 2px solid #3ea6ff;
    }
    .self-view video {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .participants {
      flex: 1;
      background: #1a1a1a;
      border-radius: 8px;
      padding: 8px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
      min-width: 200px;
    }
    .participant-video {
      width: 100%;
      aspect-ratio: 4/3;
      background: #2a2a2a;
      border-radius: 6px;
      overflow: hidden;
      position: relative;
    }
    .participant-video video {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .participant-label {
      position: absolute;
      bottom: 4px;
      left: 4px;
      background: rgba(0,0,0,0.6);
      padding: 2px 6px;
      border-radius: 4px;
      font-size: 0.8rem;
    }
  </style>
</head>
<body>
  <div class="top-bar">
    <input type="text" id="youtubeUrl" placeholder="YouTube Live video ID or URL" value="jfKfPfyJRdk">
    <button id="loadBtn">Watch</button>
    <button id="broadcastBtn">Start Broadcast</button>
    <button id="stopBroadcastBtn" class="stop" style="display:none;">Stop Broadcast</button>
    <span style="margin-left:auto;">🔴 Broadcast: <span id="status">off</span></span>
  </div>
  <div class="main">
    <div class="youtube-container">
      <div id="player"></div>
      <div class="self-view" id="selfView" style="display:none;">
        <video id="localVideo" autoplay muted playsinline></video>
      </div>
    </div>
    <div class="participants" id="participantsGrid">
      <div style="color:#888; text-align:center; padding-top:20px;">No remote participants yet. Open another tab to join.</div>
    </div>
  </div>

  <!-- YouTube IFrame API -->
  <script>
    // Load YouTube IFrame API
    const tag = document.createElement('script');
    tag.src = "https://www.youtube.com/iframe_api";
    const firstScriptTag = document.getElementsByTagName('script')[0];
    firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);

    // ----- YouTube Player -----
    let player;
    function onYouTubeIframeAPIReady() {
      player = new YT.Player('player', {
        height: '100%',
        width: '100%',
        videoId: '',
        playerVars: {
          autoplay: 1,
          controls: 1,
          modestbranding: 1,
        },
        events: {
          'onReady': onPlayerReady,
        }
      });
    }
    function onPlayerReady(event) {
      // When ready, load the default video
      loadVideo();
    }
    function loadVideo() {
      const input = document.getElementById('youtubeUrl').value.trim();
      let videoId = input;
      // Extract video ID from URL if needed
      const patterns = [
        /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/live\/)([a-zA-Z0-9_-]{11})/,
      ];
      for (const p of patterns) {
        const m = input.match(p);
        if (m) { videoId = m[1]; break; }
      }
      if (videoId && player && player.loadVideoById) {
        player.loadVideoById(videoId);
      }
    }
    document.getElementById('loadBtn').addEventListener('click', loadVideo);

    // ----- WebRTC & Broadcast -----
    const CHANNEL_NAME = 'livestream-watchparty';
    const bc = new BroadcastChannel(CHANNEL_NAME);
    const myId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
    console.log('My ID:', myId);

    let localStream = null;
    const peerConnections = new Map(); // peerId -> RTCPeerConnection
    const remoteStreams = new Map();   // peerId -> MediaStream (for video elements)

    // DOM Elements
    const localVideo = document.getElementById('localVideo');
    const selfView = document.getElementById('selfView');
    const broadcastBtn = document.getElementById('broadcastBtn');
    const stopBroadcastBtn = document.getElementById('stopBroadcastBtn');
    const statusSpan = document.getElementById('status');
    const participantsGrid = document.getElementById('participantsGrid');

    // Start/stop local broadcast
    broadcastBtn.addEventListener('click', startBroadcast);
    stopBroadcastBtn.addEventListener('click', stopBroadcast);

    async function startBroadcast() {
      try {
        localStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
        localVideo.srcObject = localStream;
        selfView.style.display = 'block';
        broadcastBtn.style.display = 'none';
        stopBroadcastBtn.style.display = 'inline-block';
        statusSpan.textContent = 'on';
        // Announce ourselves to the room
        bc.postMessage({ type: 'join', id: myId });
        console.log('Broadcasting started, joining room');
      } catch (err) {
        alert('Camera/mic access denied: ' + err.message);
      }
    }

    function stopBroadcast() {
      // Hang up all connections
      for (const pc of peerConnections.values()) {
        pc.close();
      }
      peerConnections.clear();
      remoteStreams.clear();
      // Stop local tracks
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
        localStream = null;
      }
      localVideo.srcObject = null;
      selfView.style.display = 'none';
      broadcastBtn.style.display = 'inline-block';
      stopBroadcastBtn.style.display = 'none';
      statusSpan.textContent = 'off';
      // Clear remote video grid
      participantsGrid.innerHTML = '<div style="color:#888;text-align:center;padding-top:20px;">No remote participants.</div>';
      // Announce leave
      bc.postMessage({ type: 'leave', id: myId });
    }

    // Handle incoming signalling messages
    bc.onmessage = (event) => {
      const msg = event.data;
      if (!msg || msg.id === myId) return; // ignore own messages

      if (msg.type === 'join') {
        // A new peer joined, initiate connection as offerer
        handleNewPeer(msg.id);
      }
      else if (msg.type === 'offer' && msg.to === myId) {
        handleOffer(msg.from, msg.sdp);
      }
      else if (msg.type === 'answer' && msg.to === myId) {
        handleAnswer(msg.from, msg.sdp);
      }
      else if (msg.type === 'ice-candidate' && msg.to === myId) {
        handleIceCandidate(msg.from, msg.candidate);
      }
      else if (msg.type === 'leave') {
        handlePeerLeave(msg.id);
      }
    };

    // Offerer side: create connection to a new peer
    function handleNewPeer(peerId) {
      if (peerConnections.has(peerId)) return;
      const pc = createPeerConnection(peerId);
      // Add local tracks to new connection
      if (localStream) {
        localStream.getTracks().forEach(track => pc.addTrack(track, localStream));
      }
      // Create offer
      pc.createOffer()
        .then(offer => {
          return pc.setLocalDescription(offer);
        })
        .then(() => {
          bc.postMessage({ type: 'offer', sdp: pc.localDescription, from: myId, to: peerId });
        })
        .catch(err => console.error('Error creating offer:', err));
    }

    // Answerer side: handle incoming offer
    async function handleOffer(peerId, sdp) {
      if (peerConnections.has(peerId)) {
        // already connected, maybe renegotiate? For simplicity, ignore.
        return;
      }
      const pc = createPeerConnection(peerId);
      if (localStream) {
        localStream.getTracks().forEach(track => pc.addTrack(track, localStream));
      }
      try {
        await pc.setRemoteDescription(new RTCSessionDescription(sdp));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        bc.postMessage({ type: 'answer', sdp: pc.localDescription, from: myId, to: peerId });
      } catch (err) {
        console.error('Error handling offer:', err);
      }
    }

    // Offerer side: handle answer
    async function handleAnswer(peerId, sdp) {
      const pc = peerConnections.get(peerId);
      if (!pc) return;
      try {
        await pc.setRemoteDescription(new RTCSessionDescription(sdp));
      } catch (err) {
        console.error('Error setting remote description from answer:', err);
      }
    }

    // Handle ICE candidate
    function handleIceCandidate(peerId, candidate) {
      const pc = peerConnections.get(peerId);
      if (!pc) return;
      try {
        pc.addIceCandidate(new RTCIceCandidate(candidate));
      } catch (err) {
        console.error('Error adding ICE candidate:', err);
      }
    }

    // Remove peer when they leave
    function handlePeerLeave(peerId) {
      const pc = peerConnections.get(peerId);
      if (pc) {
        pc.close();
        peerConnections.delete(peerId);
      }
      // Remove the video element for this peer
      const videoEl = document.getElementById(`remote-${peerId}`);
      if (videoEl) videoEl.parentElement.remove();
      remoteStreams.delete(peerId);
      if (participantsGrid.children.length === 0) {
        participantsGrid.innerHTML = '<div style="color:#888;text-align:center;padding-top:20px;">No remote participants.</div>';
      }
    }

    // Create and configure RTCPeerConnection
    function createPeerConnection(peerId) {
      const configuration = { iceServers: [{ urls: 'stun:stun.l.google.com:19302' }] };
      const pc = new RTCPeerConnection(configuration);
      peerConnections.set(peerId, pc);

      // Send ICE candidates
      pc.onicecandidate = (event) => {
        if (event.candidate) {
          bc.postMessage({
            type: 'ice-candidate',
            candidate: event.candidate,
            from: myId,
            to: peerId
          });
        }
      };

      // Handle incoming remote stream
      pc.ontrack = (event) => {
        const remoteStream = event.streams[0];
        if (!remoteStream) return;
        remoteStreams.set(peerId, remoteStream);
        // Add or update video element
        let videoEl = document.getElementById(`remote-${peerId}`);
        if (!videoEl) {
          // Create container
          const container = document.createElement('div');
          container.className = 'participant-video';
          videoEl = document.createElement('video');
          videoEl.id = `remote-${peerId}`;
          videoEl.autoplay = true;
          videoEl.playsInline = true;
          videoEl.muted = false; // unmute remote for demo
          const label = document.createElement('div');
          label.className = 'participant-label';
          label.textContent = `Peer ${peerId.slice(-4)}`;
          container.appendChild(videoEl);
          container.appendChild(label);
          // Remove placeholder if present
          const placeholder = participantsGrid.querySelector('div:first-child');
          if (placeholder && placeholder.textContent.includes('No remote participants')) {
            placeholder.remove();
          }
          participantsGrid.appendChild(container);
        }
        // Set stream
        if (videoEl.srcObject !== remoteStream) {
          videoEl.srcObject = remoteStream;
        }
      };

      pc.onconnectionstatechange = () => {
        if (pc.connectionState === 'failed' || pc.connectionState === 'disconnected') {
          handlePeerLeave(peerId);
        }
      };

      return pc;
    }

    // Clean up on page unload
    window.addEventListener('beforeunload', () => {
      bc.postMessage({ type: 'leave', id: myId });
      // Close all connections
      for (const pc of peerConnections.values()) {
        pc.close();
      }
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    });
  </script>
</body>
</html>
```

## How it works

**1. YouTube Live + Multi‑party video call**  
The left pane holds a YouTube IFrame Player (live or regular video).  
The right pane shows a grid of remote participants – just like a Zoom call.

**2. Pure client‑side signalling with BroadcastChannel**  
No server is needed for the demo. All tabs on the same origin communicate via `BroadcastChannel`.  
- When you click **Start Broadcast**, the page captures your camera/mic and announces your presence.  
- Any other open tab receives `join`, automatically creates a WebRTC connection and exchanges SDP/ICE candidates.  
- Remote video streams appear in the participants grid.

**3. Mesh topology**  
Every peer connects directly to every other peer. This works well for small groups (2‑5 people). For larger calls a Selective Forwarding Unit (SFU) would be recommended.

## How to test it

1. Save the code as `index.html`.
2. Serve it locally (required for `getUserMedia` secure context).  
   Example: `npx serve .` or `python3 -m http.server 8000`.
3. Open the URL in **two (or more) browser tabs**.
4. Enter a YouTube Live video ID (or keep the default lofi stream).
5. In each tab, click **Start Broadcast** and grant camera/mic permission.
6. You’ll see the remote video(s) appear on the right while the YouTube stream plays on the left.

## Going to production

- Replace `BroadcastChannel` with a WebSocket‑based signalling server (e.g., Socket.IO).  
- Add a TURN server to the `iceServers` configuration for reliable connectivity behind NATs.  
- For more than 4‑5 participants, replace the mesh with an SFU (like mediasoup, Janus, or a cloud service).  
- Add room management, mute/unmute, screen sharing, and a chat overlay.

This is a full‑fledged watch‑party + video‑conference client built entirely with browser APIs. Let me know if you want to extend any part! 💪

You’re asking for a creator‑style dashboard: **watch someone else’s YouTube Live while you are live on YouTube yourself**, with live chat segregation and a layout that squeezes every pixel for efficiency.  
Below is a pure client‑side demo that puts all that together – YouTube player, embedded live chats, your own broadcast preview, and a simulated multi‑viewer chat using only the browser (no server).

## What the demo does

- **Watch a YouTube live stream** – enter any video ID (left pane).  
- **Your own broadcast preview** – your webcam feed (right pane) with a “Go Live” button.  
- **Two segregated live‑chat panels**  
  - *Watched stream chat* – embedded YouTube live chat iframe (real chat if the stream is live).  
  - *Your broadcast chat* – simulated viewer chat; open a second tab as a “viewer” and send messages that appear only in the broadcaster’s chat panel.  
- **Layout maximizes screen space** – collapsible panels, resizable (drag the middle border).  
- All signalling done over `BroadcastChannel`, so no server is required.

> **Real YouTube broadcasting** (ingesting your stream to YouTube) requires server‑side OAuth and an RTMP or WebRTC ingestion endpoint. The demo simulates that with a local preview and a mock viewer chat you can test instantly. At the end I’ll show you how to upgrade to real YouTube Live ingestion.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Streamer Dashboard – Watch &amp; Broadcast with Chat</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: system-ui, sans-serif;
      background: #0b0b0b;
      color: #fff;
      height: 100vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    /* Top toolbar */
    .toolbar {
      display: flex;
      gap: 10px;
      padding: 10px;
      background: #1a1a1a;
      align-items: center;
      flex-wrap: wrap;
    }
    .toolbar input {
      padding: 6px 10px;
      border-radius: 4px;
      border: 1px solid #333;
      background: #2a2a2a;
      color: #fff;
      width: 180px;
    }
    .toolbar button {
      padding: 6px 14px;
      border: none;
      border-radius: 4px;
      font-weight: bold;
      cursor: pointer;
    }
    .btn-go-live {
      background: #ff4d4d;
      color: white;
    }
    .btn-stop {
      background: #333;
      color: #ccc;
      display: none;
    }
    .status {
      margin-left: auto;
      font-size: 0.9rem;
    }
    .status span { color: #ff4d4d; }

    /* Main grid */
    .main-grid {
      flex: 1;
      display: flex;
      min-height: 0;
      overflow: hidden;
    }

    /* Left side – watched stream */
    .watch-panel {
      flex: 1 1 60%;
      display: flex;
      flex-direction: column;
      border-right: 1px solid #333;
      min-width: 300px;
    }
    .youtube-player {
      flex: 3;
      background: #000;
      position: relative;
    }
    .youtube-player iframe {
      width: 100%;
      height: 100%;
      border: none;
    }
    .watched-chat {
      flex: 1;
      border-top: 1px solid #333;
      min-height: 150px;
    }
    .watched-chat iframe {
      width: 100%;
      height: 100%;
      border: none;
      background: #181818;
    }

    /* Right side – your broadcast */
    .broadcast-panel {
      flex: 1 1 40%;
      display: flex;
      flex-direction: column;
      min-width: 280px;
    }
    .broadcast-preview {
      flex: 1;
      background: #111;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 150px;
    }
    #localVideo {
      width: 100%;
      height: 100%;
      object-fit: contain;
      display: none;
    }
    .preview-placeholder {
      color: #555;
      font-size: 2rem;
    }
    .your-chat {
      flex: 1;
      border-top: 1px solid #333;
      display: flex;
      flex-direction: column;
      min-height: 150px;
    }
    .chat-header {
      padding: 6px 10px;
      background: #1f1f1f;
      font-weight: bold;
      font-size: 0.9rem;
      display: flex;
      justify-content: space-between;
    }
    .chat-messages {
      flex: 1;
      overflow-y: auto;
      padding: 8px;
      background: #0f0f0f;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .chat-message {
      word-break: break-word;
      font-size: 0.85rem;
    }
    .chat-message .author {
      font-weight: bold;
      color: #3ea6ff;
      margin-right: 6px;
    }
    .chat-input-area {
      display: flex;
      padding: 6px;
      border-top: 1px solid #333;
      background: #1a1a1a;
    }
    .chat-input-area input {
      flex: 1;
      padding: 6px;
      border-radius: 4px;
      border: none;
      background: #2a2a2a;
      color: white;
    }
    .chat-input-area button {
      margin-left: 6px;
      padding: 6px 12px;
      background: #3ea6ff;
      border: none;
      border-radius: 4px;
      font-weight: bold;
      cursor: pointer;
    }

    /* Resize handle (simple drag) */
    .resize-handle {
      width: 4px;
      background: #333;
      cursor: col-resize;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <input id="watchVideoId" placeholder="YouTube Video ID (to watch)" value="jfKfPfyJRdk">
    <button id="loadWatchBtn">Load</button>
    <input id="ownVideoId" placeholder="Your live video ID (for chat)" value="">
    <button id="loadOwnChatBtn">Load Your Chat</button>
    <button id="goLiveBtn" class="btn-go-live">🔴 Go Live</button>
    <button id="stopLiveBtn" class="btn-stop">Stop Broadcast</button>
    <div class="status">Your stream: <span id="streamStatus">off</span></div>
  </div>

  <div class="main-grid">
    <!-- WATCH PANEL -->
    <div class="watch-panel" id="watchPanel">
      <div class="youtube-player" id="player"></div>
      <div class="watched-chat" id="watchedChatContainer">
        <iframe id="watchedChatIframe" style="display:none;" allow="autoplay; encrypted-media"></iframe>
        <div style="color:#666; padding:20px; text-align:center;">Enter a video ID and press "Load" to show live chat</div>
      </div>
    </div>
    <!-- RESIZE HANDLE -->
    <div class="resize-handle" id="resizeHandle"></div>
    <!-- BROADCAST PANEL -->
    <div class="broadcast-panel" id="broadcastPanel">
      <div class="broadcast-preview">
        <video id="localVideo" autoplay muted playsinline></video>
        <div id="previewPlaceholder" class="preview-placeholder">📷 Your camera preview</div>
      </div>
      <div class="your-chat" id="yourChatPanel">
        <div class="chat-header">
          <span>💬 Your broadcast chat</span>
          <span id="viewerCount">0 viewers</span>
        </div>
        <div class="chat-messages" id="yourChatMessages"></div>
        <div class="chat-input-area" id="viewerChatInputArea" style="display:none;">
          <input id="viewerChatInput" placeholder="Send a message as a viewer...">
          <button id="sendViewerMsgBtn">Send</button>
        </div>
        <div id="broadcasterNotice" style="padding:10px;color:#888;text-align:center;">
          Open another tab as a <b>viewer</b> and send messages here.
        </div>
      </div>
    </div>
  </div>

  <!-- YouTube IFrame API -->
  <script>
    // Load YouTube API
    const tag = document.createElement('script');
    tag.src = "https://www.youtube.com/iframe_api";
    const firstScriptTag = document.getElementsByTagName('script')[0];
    firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);

    // ---------- YouTube Player ----------
    let player;
    window.onYouTubeIframeAPIReady = () => {
      player = new YT.Player('player', {
        videoId: '',
        playerVars: {
          autoplay: 1,
          controls: 1,
          modestbranding: 1,
        },
        events: {
          'onReady': () => loadWatchVideo(),
        }
      });
    };

    function loadWatchVideo() {
      const videoId = document.getElementById('watchVideoId').value.trim() || 'jfKfPfyJRdk';
      if (player && player.loadVideoById) {
        player.loadVideoById(videoId);
        // Also update watched chat iframe
        updateWatchedChat(videoId);
      }
    }

    document.getElementById('loadWatchBtn').addEventListener('click', loadWatchVideo);

    // ---------- Watched stream chat ----------
    function updateWatchedChat(videoId) {
      const iframe = document.getElementById('watchedChatIframe');
      const container = document.getElementById('watchedChatContainer');
      const placeholder = container.querySelector('div:not(#watchedChatIframe)');
      if (!videoId) {
        iframe.style.display = 'none';
        if (placeholder) placeholder.style.display = 'block';
        return;
      }
      // YouTube live chat embed (only works if live & chat enabled)
      iframe.src = `https://www.youtube.com/live_chat?v=${videoId}&embed_domain=${window.location.hostname}`;
      iframe.style.display = 'block';
      if (placeholder) placeholder.style.display = 'none';
    }

    // Optional: Load your own live chat (if you are actually live)
    document.getElementById('loadOwnChatBtn').addEventListener('click', () => {
      const ownVideoId = document.getElementById('ownVideoId').value.trim();
      // In a real setup, you'd embed your own chat. Here we just alert.
      if (ownVideoId) {
        alert(`To see your own live chat, embed: https://www.youtube.com/live_chat?v=${ownVideoId}`);
        // You could create a second iframe, but space is limited. This is just for demo.
      }
    });

    // ---------- Simulated Broadcast & Viewer Chat (BroadcastChannel) ----------
    const CHANNEL_NAME = 'streamer-dashboard';
    const bc = new BroadcastChannel(CHANNEL_NAME);
    const myId = Date.now().toString(36) + Math.random().toString(36).substr(2,5);
